'use client';

import { useEffect, useState } from 'react';
import toast, { Toaster } from 'react-hot-toast';
import { Dialog } from '@headlessui/react';

interface CarOwner {
  id: string;
  name: string;
  number_plate: string;
  car_type: string;
  phone_number: string;
  check_in_time: string;
  checked_out: boolean;
}

export default function CarsPage() {
  const [carOwners, setCarOwners] = useState<CarOwner[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedOwner, setSelectedOwner] = useState<CarOwner | null>(null);
  const [search, setSearch] = useState('');

  useEffect(() => {
    fetchCarOwners();
    const interval = setInterval(fetchCarOwners, 60000);
    return () => clearInterval(interval);
  }, []);

  const fetchCarOwners = async () => {
    try {
      // const res = await fetch('http://127.0.0.1:8000/car-owners/');
      const res = await fetch('https://parkingapp-production-1068.up.railway.app/car-owners/');
      const data = await res.json();
      setCarOwners(data);
    } catch (error) {
      toast.error('Failed to fetch car owners!');
    }
  };

  const saveOwner = async () => {
    try {
      const isNew = selectedOwner?.id === '';
      const url = isNew
        // ? 'http://127.0.0.1:8000/car-owners/'
        // : `http://127.0.0.1:8000/car-owners/${selectedOwner?.id}/`;
        ? 'hhttps://parkingapp-production-1068.up.railway.app/car-owners/'
        : `https://parkingapp-production-1068.up.railway.app/${selectedOwner?.id}/`;

      const method = isNew ? 'POST' : 'PUT';

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(selectedOwner),
      });

      if (res.ok) {
        toast.success(isNew ? 'Created successfully' : 'Updated successfully');
        fetchCarOwners();
        closeModal();
      } else {
        toast.error(`${isNew ? 'Creation' : 'Update'} failed`);
      }
    } catch {
      toast.error(`Error ${selectedOwner?.id ? 'updating' : 'creating'} car owner`);
    }
  };

  // ----------------------------------------------------------------------------------------------------------------------------------
  // Modal confirmation
  // Added by Ruth - confirmation before checkout
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [selectedOwnerForCheckout, setSelectedOwnerForCheckout] = useState<CarOwner | null>(null);


  const confirmCheckout = async (id: string) => {
  try {
    const res = await fetch(`hhttps://parkingapp-production-1068.up.railway.app/car-owners/${id}/checkout`, {
      method: 'PATCH',
    });
    if (res.ok) {
      toast.success('Checked out successfully');
      fetchCarOwners();
    } else {
      toast.error('Checkout failed');
    }
  } catch {
    toast.error('Error during checkout');
  } finally {
    setIsDialogOpen(false);
    setSelectedOwnerForCheckout(null);
  }
};

  const checkoutOwner = (owner: CarOwner) => {
  setSelectedOwnerForCheckout(owner);
  setIsDialogOpen(true);
};

  // --------------------------------------------------------------------------------------------------------------------------------------


  const getDuration = (checkIn: string): string => {
    const diffMs = new Date().getTime() - new Date(checkIn).getTime();
    const minutes = Math.floor(diffMs / 60000);
    const hours = Math.floor(minutes / 60);
    const remainingMinutes = minutes % 60;
    return `${hours}h ${remainingMinutes}m`;
  };

  const getCost = (checkIn: string, checkedOut: boolean): string => {
    if (checkedOut) return 'Finalized';
    const diffMs = new Date().getTime() - new Date(checkIn).getTime();
    const hours = Math.ceil(diffMs / (1000 * 60 * 60));
    return `${hours * 50} KES`;
  };

  const openModal = (owner: CarOwner) => {
    setSelectedOwner(owner);
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setSelectedOwner(null);
  };

 const filteredOwners = carOwners
  .filter(o => !o.checked_out) // hide checked-out entries -- Added by Ruth
  .filter(o => o.number_plate.toLowerCase().includes(search.toLowerCase()));

  return (
    <div className="min-h-screen bg-gray-100 p-4 sm:p-8 text-xs sm:text-sm md:text-base">
      <Toaster />

      <div className="flex flex-col sm:flex-row justify-between items-center mb-6 gap-4">
        <h1 className="text-lg sm:text-xl md:text-2xl font-bold text-gray-800">Cars in Parking</h1>
        <input
          type="text"
          placeholder="Search by plate"
          value={search}
          onChange={e => setSearch(e.target.value)}
          className="border border-green-800 text-black p-2 rounded w-full sm:w-auto"
        />
        <button
          onClick={() => {
            setSelectedOwner({
              id: '',
              name: '',
              number_plate: '',
              car_type: '',
              phone_number: '',
              check_in_time: new Date().toISOString(),
              checked_out: false,
            });
            setIsModalOpen(true);
          }}
          className="bg-green-800 text-white px-4 py-2 rounded hover:bg-green-700"
        >
          + New Car Owner
        </button>
      </div>

      <div className="overflow-x-auto rounded-lg shadow">
        <table className="min-w-full bg-white">
          <thead className="bg-green-800 text-white uppercase">
            <tr>
              <th className="py-2 px-4 text-left">Name</th>
              <th className="py-2 px-4 text-left">Number Plate</th>
              <th className="hidden sm:table-cell py-2 px-4 text-left">Type</th>
              <th className="hidden sm:table-cell py-2 px-4 text-left">Phone</th>
              <th className="hidden sm:table-cell py-2 px-4 text-left">Check-In</th>
              <th className="hidden sm:table-cell py-2 px-4 text-left">Duration</th>
              <th className="hidden sm:table-cell py-2 px-4 text-left">Cost</th>
              <th className="py-2 px-4 text-center">Actions</th>
            </tr>
          </thead>
          <tbody className="text-gray-700">
            {filteredOwners.map(owner => (
              <tr key={owner.id} className="border-b border-green-800 hover:bg-green-50">
                <td className="py-2 px-4">{owner.name}</td>
                <td className="py-2 px-4">{owner.number_plate}</td>
                <td className="hidden sm:table-cell py-2 px-4">{owner.car_type}</td>
                <td className="hidden sm:table-cell py-2 px-4">{owner.phone_number}</td>
                <td className="hidden sm:table-cell py-2 px-4">
                  {new Date(owner.check_in_time).toLocaleString()}
                </td>
                <td className="hidden sm:table-cell py-2 px-4">{getDuration(owner.check_in_time)}</td>
                <td className="hidden sm:table-cell py-2 px-4">{getCost(owner.check_in_time, owner.checked_out)}</td>
                <td className="py-2 px-4 text-center space-x-2">
                  <div className="flex flex-wrap gap-1">
                    <button
                      onClick={() => openModal(owner)}
                      className="bg-orange-600 text-white px-2 py-1 text-sm sm:text-base sm:px-3 sm:py-2 rounded hover:bg-orange-500"
                    >
                      Update
                    </button>

                    {!owner.checked_out && (
                      <button
                        onClick={() => {
                          checkoutOwner(owner);
                        }}
                        className="bg-green-800 text-white px-2 py-1 text-sm sm:text-base sm:px-3 sm:py-2 rounded hover:bg-green-700"
                      >
                        Checkout
                      </button>
                    )}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <Dialog open={isModalOpen} onClose={closeModal} className="relative z-50">
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md rounded-xl text-black bg-white p-6 shadow-lg text-sm">
            <Dialog.Title className="text-lg font-bold mb-4">
              {selectedOwner?.id ? 'Edit Car Owner' : 'New Car Owner'}
            </Dialog.Title>
            <div className="space-y-4">
              <input type="text" placeholder="Name" className="w-full border p-2 rounded"
                value={selectedOwner?.name || ''}
                onChange={e => setSelectedOwner({ ...selectedOwner!, name: e.target.value })} />
              <input type="text" placeholder="Number Plate" className="w-full border p-2 rounded"
                value={selectedOwner?.number_plate || ''}
                onChange={e => setSelectedOwner({ ...selectedOwner!, number_plate: e.target.value })} />
              <input type="text" placeholder="Type of Car" className="w-full border p-2 rounded"
                value={selectedOwner?.car_type || ''}
                onChange={e => setSelectedOwner({ ...selectedOwner!, car_type: e.target.value })} />
              <input type="text" placeholder="Phone Number" className="w-full border p-2 rounded"
                value={selectedOwner?.phone_number || ''}
                onChange={e => setSelectedOwner({ ...selectedOwner!, phone_number: e.target.value })} />
              <div className="flex gap-2 justify-end">
                <button className="bg-green-800 text-white px-4 py-2 rounded hover:bg-green-700" onClick={saveOwner}>
                  Save
                </button>
                <button className="bg-gray-500 text-white px-4 py-2 rounded hover:bg-gray-400" onClick={closeModal}>
                  Cancel
                </button>
              </div>
            </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      <Dialog open={isDialogOpen} onClose={() => setIsDialogOpen(false)} className="fixed z-50 inset-0 overflow-y-auto">
        <div className="flex items-center justify-center min-h-screen px-4">
        <Dialog.Panel className="bg-white p-6 rounded shadow-md max-w-md w-full">
          <Dialog.Title className="text-lg text-black font-medium"><strong>Confirm Checkout</strong></Dialog.Title>
            <Dialog.Description className="mt-2 text-sm text-black">
                Has <strong>{selectedOwnerForCheckout?.name}</strong>: <strong>{selectedOwnerForCheckout?.number_plate}</strong> paid <strong>{getCost(selectedOwnerForCheckout?.check_in_time || '', false)}</strong>?
            </Dialog.Description>
            <div className="mt-6 flex justify-end gap-2">
              <button
                onClick={() => setIsDialogOpen(false)}
                className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-500"
              >
                Cancel
              </button>

              <button
                onClick={async () => {
                  if (selectedOwnerForCheckout) {
                    await confirmCheckout(selectedOwnerForCheckout.id);
                  }
                }}
                className="px-4 py-2 bg-green-800 text-white rounded hover:bg-green-700"
              >
                Yes, Checkout
              </button>
            </div>
          </Dialog.Panel>
        </div>
    </Dialog>
    </div>
  );
}